"use strict";
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],id=()=>Date.now()+Math.random();
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const general=()=>({cliente:'',planta:'',fecha:new Date().toISOString().slice(0,10),ingeniero:'Rodrigo Medina',participantes:'',objetivo:'',descripcion:'',observaciones:'',recomendaciones:'',correo:'',cc:'',asunto:'Informe técnico SNF'});
const equipment={daf:['DAF',['Nombre equipo','Producto','Caudal m³/h','Dosis polímero ppm','Dosis coagulante ppm','SST afluente mg/L','SST efluente mg/L','Presión bomba bar','Presión saturación bar','Flujo aire L/min']],decanter:['Decanter',['Nombre equipo','Producto','Caudal m³/h','Dosis polímero ppm','SST afluente mg/L','SST clarificado mg/L','Velocidad diferencial rpm','Torque %','Punto de inyección','Humedad %']],filtro:['Filtro banda',['Nombre equipo','Producto','Caudal m³/h','Dosis polímero ppm','Consumo polímero kg/h','SST afluente mg/L','SST filtrado mg/L','Presión tela bar']]};
let S=load();function fresh(){return{type:null,step:0,g:general(),eq:[],tests:[],photos:[]}}function load(){try{return JSON.parse(localStorage.getItem('snfV3'))||fresh()}catch{return fresh()}}function save(){try{localStorage.setItem('snfV3',JSON.stringify(S))}catch{note('Reduce el tamaño o número de fotografías')}stats()}
function f(k,l,t='input',wide=''){return `<div class="field ${wide}"><label>${l}</label>${t==='textarea'?`<textarea data-g="${k}">${esc(S.g[k])}</textarea>`:`<input type="${t}" data-g="${k}" value="${esc(S.g[k])}">`}</div>`}
function render(){let tabs=$('#tabs'),p=$('#pages');if(!S.type){tabs.innerHTML='';p.innerHTML=home();bind();stats();return}let names=['Inicio','Datos',S.type==='seguimiento'?'Equipos':'Pruebas','Informe','Correo'];tabs.innerHTML=names.map((n,i)=>`<button data-step="${i}" class="${S.step===i?'active':''}">${i+1}. ${n}</button>`).join('');p.innerHTML=[home,generalPage,S.type==='seguimiento'?equipPage:labPage,reportPage,mailPage][S.step]();bind();stats()}
function home(){return `<section class="panel"><h2>Seleccione el tipo de visita</h2><div class="grid2"><button class="btn primary" data-type="seguimiento" style="min-height:110px">Visita de seguimiento</button><button class="btn primary" data-type="laboratorio" style="min-height:110px">Pruebas de laboratorio</button></div>${S.type?'<div class="actions"><button class="btn" data-new>Nueva visita</button></div>':''}</section>`}
function generalPage(){return `<section class="panel"><h2>Datos generales</h2><div class="grid2">${f('cliente','Cliente')}${f('planta','Planta')}${f('fecha','Fecha','date')}${f('ingeniero','Ingeniero')}${f('participantes','Participantes','input','wide')}${f('objetivo','Objetivo','textarea','wide')}${f('descripcion','Descripción del trabajo','textarea','wide')}</div></section>${photos()}<div class="actions"><button class="btn primary" data-next>Continuar</button></div>`}
function photos(){return `<section class="panel"><h2>Registro fotográfico</h2><label class="btn primary" for="photos">Tomar o agregar fotos</label><input id="photos" class="hidden" type="file" accept="image/*" capture="environment" multiple><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-top:14px">${S.photos.map((x,i)=>`<div><img src="${x.data}" style="width:100%;height:130px;object-fit:cover;border-radius:10px"><input data-cap="${x.id}" value="${esc(x.caption)}" placeholder="Descripción"><button class="btn" data-pdel="${x.id}">Eliminar</button></div>`).join('')||'<p class="muted">Sin fotografías.</p>'}</div></section>`}
function equipPage(){return `<section class="panel toolbar"><b>Agregar equipo:</b><button class="btn" data-add="daf">DAF</button><button class="btn" data-add="decanter">Decanter</button><button class="btn" data-add="filtro">Filtro banda</button></section>${S.eq.map(eqCard).join('')||'<section class="panel"><p>Agrega uno o más equipos.</p></section>'}<div class="actions"><button class="btn primary" data-next>Generar informe</button></div>`}
function eqCard(q,i){let rows=q.values.map((v,j)=>`<div class="erow"><span>${equipment[q.type][1][j]}</span><span></span><input data-eqid="${q.id}" data-i="${j}" value="${esc(v)}" inputmode="decimal"></div>`).join('');let nums=q.values.map(v=>Number(String(v).replace(',','.'))||0),caudal=nums[2],dose=nums[3],sst=nums[5]||0,out=nums[6]||0,carga=(caudal*sst/1000).toFixed(2),ratio=(sst?dose/sst*1000:0).toFixed(2),rem=(sst?(sst-out)/sst*100:0).toFixed(1);return `<section class="equipment"><div class="eqhead"><b>${i+1}. ${equipment[q.type][0]}</b><button class="btn" data-edel="${q.id}">Eliminar</button></div>${rows}<div class="subtitle">Cálculos automáticos</div><div class="erow"><span>Carga másica kg/h</span><span></span><input readonly value="${carga}"></div><div class="erow"><span>Ratio kg/t SST</span><span></span><input readonly value="${ratio}"></div><div class="erow"><span>Remoción SST %</span><span></span><input readonly value="${rem}"></div></section>`}
function labPage(){let keys=['muestra','producto','dosis','sst','turbiedad','resultado','observaciones'];return `<section class="panel"><h2>Pruebas de laboratorio</h2><button class="btn primary" data-test>Agregar prueba</button><div style="overflow:auto"><table class="report"><thead><tr>${keys.map(k=>`<th>${k}</th>`).join('')}<th></th></tr></thead><tbody>${S.tests.map(x=>`<tr>${keys.map(k=>`<td><input data-tid="${x.id}" data-key="${k}" value="${esc(x[k])}"></td>`).join('')}<td><button class="btn" data-tdel="${x.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div></section><div class="actions"><button class="btn primary" data-next>Generar informe</button></div>`}
function reportPage(){return `<section class="panel"><h2>Conclusiones</h2>${f('observaciones','Observaciones','textarea')}${f('recomendaciones','Recomendaciones','textarea')}</section>${report()}<div class="actions"><button class="btn" data-print>Guardar PDF</button><button class="btn primary" data-next>Preparar correo</button></div>`}
function report(){let body=S.type==='seguimiento'?S.eq.map((q,i)=>`<h3>Tabla ${i+1}. ${equipment[q.type][0]}</h3><table><tbody>${q.values.map((v,j)=>`<tr><td>${equipment[q.type][1][j]}</td><td>${esc(v)||'-'}</td></tr>`).join('')}</tbody></table>`).join(''):`<h3>Resultados</h3><table><tbody>${S.tests.map(x=>`<tr>${['muestra','producto','dosis','sst','turbiedad','resultado','observaciones'].map(k=>`<td>${esc(x[k])||'-'}</td>`).join('')}</tr>`).join('')}</tbody></table>`;return `<section class="panel"><div class="report"><b>SNF WATER SCIENCE</b><h2>Informe ${S.type==='seguimiento'?'de visita de seguimiento':'de pruebas de laboratorio'}</h2><p>${esc(S.g.cliente)} · ${esc(S.g.planta)} · ${esc(S.g.fecha)}</p><h3>Objetivo</h3><p>${esc(S.g.objetivo)||'-'}</p><h3>Descripción</h3><p>${esc(S.g.descripcion)||'-'}</p>${body}${S.photos.length?`<h3>Registro fotográfico</h3>${S.photos.map((x,i)=>`<figure><img src="${x.data}" style="max-width:100%;max-height:300px"><figcaption>Imagen ${i+1}. ${esc(x.caption)}</figcaption></figure>`).join('')}`:''}<h3>Observaciones</h3><p>${esc(S.g.observaciones)||'-'}</p><h3>Recomendaciones</h3><p>${esc(S.g.recomendaciones)||'-'}</p></div></section>`}
function mailPage(){return `<section class="panel"><h2>Enviar con Outlook móvil</h2><div class="grid2">${f('correo','Correo cliente','email')}${f('cc','CC','email')}${f('asunto','Asunto','input','wide')}</div><p class="muted">Guarda el informe como PDF y luego adjúntalo desde Descargas en Outlook.</p><div class="actions"><button class="btn" data-print>Guardar PDF</button><button class="btn primary" data-mail>Abrir Outlook móvil</button></div></section>`}
function bind(){$$('[data-type]').forEach(b=>b.onclick=()=>{S.type=b.dataset.type;S.step=1;save();render()});$$('[data-step]').forEach(b=>b.onclick=()=>{S.step=+b.dataset.step;render()});$('[data-new]')?.addEventListener('click',()=>{S=fresh();save();render()});$$('[data-g]').forEach(x=>x.oninput=()=>{S.g[x.dataset.g]=x.value;save()});$('[data-next]')?.addEventListener('click',()=>{S.step=Math.min(4,S.step+1);render()});$$('[data-add]').forEach(b=>b.onclick=()=>{let t=b.dataset.add;S.eq.push({id:id(),type:t,values:equipment[t][1].map(()=>"")});save();render()});$$('[data-eqid]').forEach(x=>x.onchange=()=>{S.eq.find(q=>q.id==x.dataset.eqid).values[+x.dataset.i]=x.value;save();render()});$$('[data-edel]').forEach(b=>b.onclick=()=>{S.eq=S.eq.filter(x=>x.id!=b.dataset.edel);save();render()});$('[data-test]')?.addEventListener('click',()=>{S.tests.push({id:id(),muestra:`Muestra ${S.tests.length+1}`,producto:'',dosis:'',sst:'',turbiedad:'',resultado:'',observaciones:''});save();render()});$$('[data-tid]').forEach(x=>x.oninput=()=>{S.tests.find(t=>t.id==x.dataset.tid)[x.dataset.key]=x.value;save()});$$('[data-tdel]').forEach(b=>b.onclick=()=>{S.tests=S.tests.filter(x=>x.id!=b.dataset.tdel);save();render()});$('#photos')?.addEventListener('change',photoInput);$$('[data-cap]').forEach(x=>x.oninput=()=>{S.photos.find(p=>p.id==x.dataset.cap).caption=x.value;save()});$$('[data-pdel]').forEach(b=>b.onclick=()=>{S.photos=S.photos.filter(x=>x.id!=b.dataset.pdel);save();render()});$$('[data-print]').forEach(b=>b.onclick=()=>{S.step=3;render();setTimeout(()=>print(),150)});$('[data-mail]')?.addEventListener('click',mail)}
async function photoInput(ev){for(const file of ev.target.files){const data=await resize(file);S.photos.push({id:id(),caption:'',data})}save();render()}function resize(file){return new Promise(ok=>{let r=new FileReader;r.onload=()=>{let im=new Image;im.onload=()=>{let s=Math.min(1,1200/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*s;c.height=im.height*s;c.getContext('2d').drawImage(im,0,0,c.width,c.height);ok(c.toDataURL('image/jpeg',.72))};im.src=r.result};r.readAsDataURL(file)})}
function mail(){if(!S.g.correo.includes('@'))return note('Ingresa un correo válido');let body=`Estimado/a:\n\nAdjunto informe de la visita realizada en ${S.g.planta} el ${S.g.fecha}.\n\nObjetivo:\n${S.g.objetivo}\n\nObservaciones:\n${S.g.observaciones}\n\nRecomendaciones:\n${S.g.recomendaciones}\n\nSaludos cordiales,\n${S.g.ingeniero}\nSNF Chile`;location.href=`ms-outlook://emails/new?${new URLSearchParams({to:S.g.correo,cc:S.g.cc,subject:S.g.asunto,body})}`}
function stats(){let a=$('#equipmentCount'),b=$('#dataCount'),c=$('#recCount');if(a)a.textContent=S.type==='laboratorio'?S.tests.length:S.eq.length;if(b)b.textContent=S.type==='laboratorio'?S.tests.filter(x=>x.resultado).length:S.eq.reduce((n,x)=>n+x.values.filter(Boolean).length,0);if(c)c.textContent=S.g.recomendaciones?'Sí':'No'}function note(t){let d=document.createElement('div');d.className='notice';d.textContent=t;document.body.appendChild(d);setTimeout(()=>d.remove(),2500)}render();if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
